<?php

declare(strict_types=1);namespace ProjectPress\Tests\Unit;use PHPUnit\Framework\TestCase;use ProjectPress\API\PeopleCommunicationRoutes;use ProjectPress\Includes\Core\Schema;use ProjectPress\Includes\Core\WP\Database;use ProjectPress\Includes\Project\Communication\Notification;use ProjectPress\Includes\Project\People\TimeSheet;final class PhaseNinePeopleCommunicationTest extends TestCase{public function testPeopleCommunicationTablesAreRegistered():void{Schema::register_tables();$tables=Database::get_core_tables();$this->assertArrayHasKey('timesheets',$tables);$this->assertArrayHasKey('project_notifications',$tables);}public function testModelsRemainProjectScoped():void{$this->assertSame(22,(new TimeSheet(array('project_id'=>22)))->get_project_id());$this->assertSame(22,(new Notification(array('project_id'=>22)))->get_project_id());}public function testRestHandlersExist():void{foreach(array('index','create','delete','can_read','can_edit')as$method)$this->assertTrue(method_exists(PeopleCommunicationRoutes::class,$method));}}
